            "niv": "\"Woe to you, teachers of the law and Pharisees, you hypocrites! You give a tenth of your spices--mint, dill and 1453 cummin. But you have neglected the more important matters of the law-- justice, mercy and faithfulness. You should have practiced the latter, without neglecting the former.",
